  const stripped = code.replace(
    /@import\s+["']tailwindcss(?:\/[^"']*)?["'](?:\s+layer\([^)]*\))?\s*;?/g,
    "",
  );

  if (stripped === code) {
    return null;
  }

  return stripped;
}

